<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';import {useRoute,useRouter} from 'vue-router';const route=useRoute(),router=useRouter(),frame=ref(null),frameHeight=ref(0);const pages={tasks:'今日路线',calendar:'日历',habits:'习惯与专注',health:'健康记录',sleep:'睡眠',library:'兴趣收藏',review:'后日谈',settings:'房间布置'};const dayPages=computed(()=>['library','settings'].includes(String(route.params.page))?{}:Object.fromEntries(Object.entries(pages).filter(([k])=>!['library','settings'].includes(k))));const page=computed(()=>pages[String(route.params.page)]?String(route.params.page):'tasks');
watch(page,()=>{frameHeight.value=0;});
/* 工具页会把自己的内容高度报上来，这里用它撑开 iframe：滚动条只留外层一条 */
function navigate(e){if(e.origin!==location.origin||e.source!==frame.value?.contentWindow)return;if(e.data?.type==='lin-space-height'){const h=Number(e.data.height)||0;if(h>=480&&h<=30000&&Math.abs(h-frameHeight.value)>2)frameHeight.value=h;return;}if(e.data?.type!=='lin-space-navigate')return;const url=String(e.data.url||'');if(/^\/workspace(?:\/[a-z]+)?(?:#.*)?$/.test(url)){const [path,hash]=url.split('#'),p=path.split('/')[2];router.push((!p?'/room':p==='writing'?'/article/articleList':'/life/'+p)+(hash?'#'+hash:''));}else if(/^\/admin\/(?:article\/(?:addArticle|articleList|editArticle)|home|profile|moments|albums|comments|registrations|taxonomy|site-settings)(?:\?.*)?$/.test(url))router.push(url.slice(6));else if(['/','/about','/login'].includes(url))location.href=url;}
function themeChanged(e){frame.value?.contentWindow?.postMessage({type:'lin-space-theme',theme:e.detail},location.origin);}onMounted(()=>{addEventListener('message',navigate);addEventListener('lin-theme',themeChanged);});onBeforeUnmount(()=>{removeEventListener('message',navigate);removeEventListener('lin-theme',themeChanged);});
</script>
<template><section class="life-tools"><div v-if="Object.keys(dayPages).length" class="life-subnav"><RouterLink v-for="(label,key) in dayPages" :key="key" :to="'/life/'+key">{{label}}</RouterLink></div><iframe ref="frame" :key="page" :src="'/space-tools/'+page+route.hash" :title="pages[page]" class="life-tool-frame" :style="frameHeight?{height:frameHeight+'px'}:undefined"/></section></template>
<style scoped>.life-subnav{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}.life-subnav a{font-size:12px;padding:9px 13px;border-radius:5px;background:var(--studio-panel);border:1px solid var(--studio-line)}.life-subnav a.router-link-active{background:#877aaa;color:white}.life-tool-frame{width:100%;height:calc(100vh - 210px);min-height:480px;border:0;border-radius:10px;background:transparent;display:block}@media(max-width:700px){.life-tool-frame{min-height:480px;height:calc(100vh - 190px)}.life-subnav{gap:5px}.life-subnav a{font-size:11px;padding:7px 10px}}</style>
